mapper.select:
SELECT
    t.*,
    (SELECT COUNT(*) FROM sys_security_audit_log WHERE 1=1
    AND is_deleted = 0

        AND user_id = #{params.userId}


        AND action_type = #{params.actionType}


        AND status = #{params.status}


        AND ip_address LIKE CONCAT('%', #{params.ipAddress}, '%')


        AND create_time >= #{params.startDate}::timestamp


        AND create_time <= #{params.endDate}::timestamp

    ) AS total
FROM (
    SELECT * FROM sys_security_audit_log
    WHERE 1=1
    AND is_deleted = 0

        AND user_id = #{params.userId}


        AND action_type = #{params.actionType}


        AND status = #{params.status}


        AND ip_address LIKE CONCAT('%', #{params.ipAddress}, '%')


        AND create_time >= #{params.startDate}::timestamp


        AND create_time <= #{params.endDate}::timestamp

    ORDER BY create_time DESC
    LIMIT #{params.pageSize} OFFSET (#{params.pageNum} - 1) * #{params.pageSize}
) t
